unsigned char scroll_buf[128*8];

void scroll_LCD(unsigned char *src, int offset)
{
    int page;
    int x;
    int pos;

    for(page = 0; page < 8; page++){
			for(x = 0; x < 128; x++){
				pos = (x + offset) % 128;
        scroll_buf[page * 128 + x] = src[page * 128 + pos];
      }
    }
		
    draw_LCD(scroll_buf);
}
	
int main(void)
{
    int i = 0;
    int old = 0;
    int mode = 0;

    int scroll_offset = 0;
    int scroll_dir = 0;

    unsigned char *current;

    SYS_Init();
    init_LCD();
    clear_LCD();

    while(1){
        i = ScanKey();

        if(i != 0 && old == 0){
            if(i == 1){
                scroll_dir = 1;
            }else if(i == 2){
                scroll_dir = 0;
            }else if(i == 3){
                scroll_dir = -1;
            }else if(i == 4){
                mode = 4;
                scroll_offset = 0;
                scroll_dir = 0;
            }else if(i == 5){
                mode = 5;
                scroll_offset = 0;
                scroll_dir = 0;
            }else if(i == 6){
                mode = 6;
                scroll_offset = 0;
                scroll_dir = 0;
            }else if(i == 7){
                mode = 7;
                scroll_offset = 0;
                scroll_dir = 0;
            }
        }

        old = i;

        if(mode == 0 || mode == 4){
            current = student;
        }else if(mode == 5){
            current = ta1;
        }else if(mode == 6){
            current = ta2;
        }else{
            current = tea;
        }

        if(scroll_dir != 0){
            scroll_offset += scroll_dir;

            if(scroll_offset >= 128){
                scroll_offset = 0;
            }

            if(scroll_offset < 0){
                scroll_offset = 127;
            }
        }
				
        scroll_LCD(current, scroll_offset);
        CLK_SysTickDelay(20000);
    }
}
